// rc_world.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



//*****************************************************************************
// Init-time table builders
//*****************************************************************************
static uint32_t ScaleRgb(uint32_t rgb, uint16_t m)      // m is Q8
{
    uint32_t r = (((rgb >> 16) & 0xFFUL) * m) >> 8;
    uint32_t g = (((rgb >>  8) & 0xFFUL) * m) >> 8;
    uint32_t b = (( rgb        & 0xFFUL) * m) >> 8;
    return (r << 16) | (g << 8) | b;
}


// All sprite colours share one id table (ids ID_SPR..), de-duplicated by RGB value:
// palettes are free to repeat colours and there is no 8-colours-per-palette id limit.
static uint16_t s_nCol;

static uint16_t ColorId(uint32_t rgb)
{
    uint16_t i;

    for(i = 0; i < s_nCol; i++)
        if(rc_sprRgb[i] == rgb) return (uint16_t)(ID_SPR + i);
    if(s_nCol < SPR_COLORS)
    {
        rc_sprRgb[s_nCol] = rgb;
        return (uint16_t)(ID_SPR + s_nCol++);
    }
    return (uint16_t)(ID_SPR + SPR_COLORS - 1);         // table full: reuse the last colour
}


static void SetPal(uint16_t type, const PalEnt *list)
{
    uint16_t i;

    for(i = 0; i < PAL_N; i++) rc_palId[type][i] = ColorId(COLOR_MAGENTA);   // magenta = missing
    for(i = 0; list[i].ch; i++)
        if((uint16_t)(list[i].ch - 'a') < PAL_N)
            rc_palId[type][list[i].ch - 'a'] = ColorId(list[i].rgb);
}


// Switch the wall theme: recolours the stone, mortar and accent colours and the floor and ceiling.
void rc_ApplyTheme(uint16_t t)
{
#if !RC_WALL_THEMES
    if(t != TH_BASEMENT) t = TH_BASEMENT;               // boss themes switched off
#endif
    const Theme *th = &rc_kTheme[t];
    uint16_t     sh;

    rc_theme = t;
    for(sh = 0; sh < 4; sh++)
    {
        rc_wallCol[1][sh][0] = ScaleRgb(th->base, rc_kShadeMul[sh]);
        rc_wallCol[1][sh][1] = ScaleRgb(rc_wallCol[1][sh][0], 200);
        rc_wallCol[2][sh][0] = ScaleRgb(th->base, (uint16_t)((rc_kShadeMul[sh] * 5u) >> 2));     // pillars: lighter stone
        rc_wallCol[2][sh][1] = ScaleRgb(rc_wallCol[2][sh][0], 200);
        rc_themeCol[0][sh][0] = ScaleRgb(th->mortar, rc_kShadeMul[sh]);
        rc_themeCol[0][sh][1] = ScaleRgb(rc_themeCol[0][sh][0], 200);
        rc_themeCol[1][sh][0] = ScaleRgb(th->accent, rc_kShadeMul[sh]);
        rc_themeCol[1][sh][1] = ScaleRgb(rc_themeCol[1][sh][0], 200);
    }
    rc_colFloor = th->floor;
    rc_colCeil  = th->ceil;
    rc_invalidate = true;                       // everything on screen has a new colour
    rc_viewDirty  = 2;
}


uint16_t rc_ThemeOfMini(uint16_t type)
{
    switch(type)
    {
        case ET_SLIMEKING: return TH_SLIME;
        case ET_GOLEM:     return TH_GOLEM;
        case ET_VAMPIRE:   return TH_VAMPIRE;
        case ET_EYEKING:   return TH_EYE;
        case ET_LICH:      return TH_LICH;
        default:           return TH_BASEMENT;
    }
}


void rc_BuildTables(void)
{
    uint16_t i, c, sh;
    float    s, f;

    if(rc_tablesReady) return;

    for(i = 0; i <= 256; i++)
    {
        s = sinf((float)i * (6.2831853f / RC_ANGLES));

        rc_qsin[i] = (int16_t)(s * 16384.0f + 0.5f);

        f = (fabsf(s) < 0.0001f) ? 65535.0f : 256.0f / fabsf(s);
        rc_qinv[i] = (f > 65535.0f) ? 65535u : (uint16_t)f;
    }

    for(c = 0; c < RC_COLS; c++)
    {
        int16_t off = (int16_t)(((int32_t)(2 * (int16_t)c - (RC_COLS - 1)) * RC_FOV_UNITS)
                                / (2 * RC_COLS));
        rc_colOff[c] = off;
        rc_colCos[c] = COS(off);
    }

    for(i = 0; i <= 256; i++)
        rc_atan[i] = (int16_t)(atanf((float)i / 256.0f) * (RC_ANGLES / 6.2831853f) + 0.5f);

    // Wall colours: tiles 1..5, 4 distance shades, 2 sides (side 1 is darker).
    for(i = 1; i < TILE_KINDS; i++)
        for(sh = 0; sh < 4; sh++)
        {
            rc_wallCol[i][sh][0] = ScaleRgb(rc_kWallBase[i], rc_kShadeMul[sh]);
            rc_wallCol[i][sh][1] = ScaleRgb(rc_wallCol[i][sh][0], 200);
        }

    s_nCol = 0;
    for(i = 0; i < PT_COUNT; i++) SetPal(i, rc_kPal[i]);
    rc_ApplyTheme(TH_BASEMENT);

    rc_tablesReady = true;
}


void rc_LoadMap(void)
{
    uint16_t x, y, t, k;
    int32_t  sx[RC_NUM_DOORS + 1], sy[RC_NUM_DOORS + 1];    // sums for the door centres
    uint16_t cnt[RC_NUM_DOORS + 1];

    rc_spCount = 0;
    rc_evX[0] = rc_evX[1] = 0;
    rc_evY[0] = rc_evY[1] = 0;
    for(k = 0; k <= RC_NUM_DOORS; k++) { sx[k] = 0; sy[k] = 0; cnt[k] = 0; }

    for(y = 0; y < RC_MAP_H; y++)
        for(x = 0; x < RC_MAP_W; x++)
        {
            char ch = rc_kMaps[0][y][x];

            t = 0;

            if(ch >= 'a' && ch <= 'g')                  // spawn marker, letter = section
            {
                if(rc_spCount < RC_MAX_SPAWNS)
                {
                    rc_spX[rc_spCount]   = (int16_t)((x << 10) + 512);
                    rc_spY[rc_spCount]   = (int16_t)((y << 10) + 512);
                    rc_spSec[rc_spCount] = (uint16_t)(ch - 'a');
                    rc_spCount++;
                }
            }
            else if(ch == '*')                         // hallway alcove: merchant / chest spot
            {
                k = (x < RC_MAP_W / 2u) ? 0u : 1u;
                rc_evX[k] = (int16_t)((x << 10) + 512);
                rc_evY[k] = (int16_t)((y << 10) + 512);
            }
            else if(ch == '7')                         // special metal Dragon Den door
            {
                t = TILE_METAL_DOOR;
            }
            else if(ch >= '1' && ch <= '6')             // purchasable wooden door tile
            {
                k = (uint16_t)(ch - '0');
                t = TILE_DOOR;
                sx[k] += (int32_t)((x << 10) + 512);
                sy[k] += (int32_t)((y << 10) + 512);
                cnt[k]++;
            }
            else
            {
                switch(ch)
                {
                    case '#': t = 1; break;
                    case 'P': t = 2; break;
                    case 'B': t = 3; break;
                    case '@':
                        rc_px = (int16_t)((x << 10) + 512);
                        rc_py = (int16_t)((y << 10) + 512);
                        break;
                    default: break;
                }
            }
            rc_tile[(y << RC_MAP_SHIFT) + x] = t;
        }

    for(k = 1; k <= RC_NUM_DOORS; k++)
        if(cnt[k])
        {
            rc_doorCx[k] = (int16_t)(sx[k] / (int32_t)cnt[k]);
            rc_doorCy[k] = (int16_t)(sy[k] / (int32_t)cnt[k]);
        }
}


//*****************************************************************************
// The ray caster: grid DDA, all integer, over a 32 x 32 world.
//   angle : 0..1023
//   returns the distance ALONG the ray in Q8 (not yet fisheye-corrected)
//   *tile = wall type hit (1..5), *side = 0 for a x-face, 1 for a y-face
// Start point comes from the player position.
//*****************************************************************************
uint16_t rc_RC_CastRay(int16_t angle, uint16_t *tile, uint16_t *side)
{
    uint16_t a     = (uint16_t)angle & RC_ANGLE_MASK;
    int16_t  c     = COS(a);
    int16_t  s     = SIN(a);
    uint16_t dX    = QInv((uint16_t)(a + 256u));
    uint16_t dY    = QInv(a);
    int16_t  mx    = (int16_t)(rc_px >> 10);
    int16_t  my    = (int16_t)(rc_py >> 10);
    uint16_t fx    = (uint16_t)(rc_px >> 2) & 255u;         // fraction inside tile, Q8
    uint16_t fy    = (uint16_t)(rc_py >> 2) & 255u;
    int16_t  stepX, stepY;
    uint32_t sideX, sideY, dist = 0;
    uint16_t hit = 1, sd = 0, i;

    if(c < 0) { stepX = -1; sideX = ((uint32_t)fx * dX) >> 8; }
    else      { stepX =  1; sideX = ((uint32_t)(256u - fx) * dX) >> 8; }

    if(s < 0) { stepY = -1; sideY = ((uint32_t)fy * dY) >> 8; }
    else      { stepY =  1; sideY = ((uint32_t)(256u - fy) * dY) >> 8; }

    for(i = 0; i < RC_MAX_STEPS; i++)
    {
        if(sideX < sideY) { dist = sideX; sideX += dX; mx += stepX; sd = 0; }
        else              { dist = sideY; sideY += dY; my += stepY; sd = 1; }

        if((uint16_t)mx >= RC_MAP_W || (uint16_t)my >= RC_MAP_H) { hit = 1; break; }

        hit = rc_tile[((uint16_t)my << RC_MAP_SHIFT) + (uint16_t)mx];
        if(hit) break;
    }

    *tile = (hit == 0 || hit >= TILE_KINDS) ? 1u : hit;
    *side = sd;
    return (dist > 65535UL) ? 65535u : (uint16_t)dist;
}
